import { useEffect, useMemo, useRef, useState } from 'react';
import { apiFetch } from './api';
// The planner is one self-contained page (its own styles, its own drag code), generated by
// bluewater-labor-costing/src/mold_planner.cjs. It runs in a frame so none of its CSS or
// print rules can touch the rest of B.O.S.S, and nothing here writes to the server:
// the plan lives in this browser (localStorage) until it gets a home in the database.
import page from './moldPlanner/planner.html?raw';
import plan from './moldPlanner/plan.json';

export default function MoldPlanner() {
  const [names, setNames] = useState(null);   // boat_id -> customer; null while loading
  const [height, setHeight] = useState(620);
  const frame = useRef(null);

  // The only thing read from B.O.S.S: customer names for the bars (the bundled plan carries
  // hull numbers only). If it fails the planner still opens, showing hull numbers.
  useEffect(() => {
    let live = true;
    apiFetch('/api/boats')
      .then(r => (r.ok ? r.json() : []))
      .then(list => {
        if (!live) return;
        const m = {};
        for (const b of Array.isArray(list) ? list : []) if (b?.boat_id) m[b.boat_id] = b.customer_name || b.customer || '';
        setNames(m);
      })
      .catch(() => { if (live) setNames({}); });
    return () => { live = false; };
  }, []);

  // Fill the window below the tab bar.
  useEffect(() => {
    const fit = () => {
      if (!frame.current) return;
      const top = frame.current.getBoundingClientRect().top;
      setHeight(Math.max(480, Math.round(window.innerHeight - top - 14)));
    };
    fit();
    window.addEventListener('resize', fit);
    return () => window.removeEventListener('resize', fit);
  }, [names]);

  const doc = useMemo(() => {
    if (!names) return null;
    const data = { ...plan, boats: plan.boats.map(b => ({ ...b, cust: names[b.id] || b.cust || '' })) };
    return page.replace('/*DATA*/null', () => JSON.stringify(data).replace(/</g, '\\u003c'));
  }, [names]);

  if (!doc) return <div className="loading">Loading…</div>;
  return (
    <iframe
      ref={frame}
      title="Mold Planner"
      srcDoc={doc}
      style={{ display: 'block', width: '100%', height, border: 0 }}
    />
  );
}
